def np_to_qpixmap(img: np.ndarray) -> QPixmap:
    if img.ndim == 2:
        h, w = img.shape
        qimg = QImage(img.data, w, h, w, QImage.Format_Grayscale8)
    else:
        h, w, ch = img.shape
        if ch == 3 and hasattr(QImage, "Format_BGR888"):
            img_bgr = np.ascontiguousarray(img)
            qimg = QImage(img_bgr.data, w, h, ch * w, QImage.Format_BGR888)
        elif ch == 3:
            img_rgb = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)
            qimg = QImage(img_rgb.data, w, h, ch * w, QImage.Format_RGB888)
        elif ch == 4:
            img_rgba = cv2.cvtColor(img, cv2.COLOR_BGRA2RGBA)
            qimg = QImage(img_rgba.data, w, h, ch * w, QImage.Format_RGBA8888)
        else:
            raise ValueError(f"Unsupported channel count: {ch}")

    return QPixmap.fromImage(qimg.copy())  # đź”Ą TO JEST KLUCZ


def qimage_to_bgr_array(image: QImage) -> np.ndarray | None:
    if image is None or image.isNull():
        return None

    converted = image.convertToFormat(QImage.Format_RGBA8888)
    width = converted.width()
    height = converted.height()
    if width <= 0 or height <= 0:
        return None

    ptr = converted.bits()
    ptr.setsize(converted.byteCount())
    rgba = np.frombuffer(ptr, dtype=np.uint8).reshape((height, width, 4))
    rgb = np.ascontiguousarray(rgba[..., :3])
    bgr = cv2.cvtColor(rgb, cv2.COLOR_RGB2BGR)
    return bgr

def svg_icon_from_text(svg_text: str, size: int = 18) -> QIcon:
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)
    if SVG_AVAILABLE and QSvgRenderer is not None:
        renderer = QSvgRenderer()
        renderer.load(QByteArray(svg_text.encode("utf-8")))
        painter = QPainter(pixmap)
        renderer.render(painter)
        painter.end()
    return QIcon(pixmap)


def apply_dialog_window_flags(widget):
    widget.setWindowFlags(widget.windowFlags() & ~Qt.WindowContextHelpButtonHint)


def apply_standard_layout_margins(layout, margins=(20, 20, 20, 20), spacing=12):
    layout.setContentsMargins(*margins)
    layout.setSpacing(spacing)


def get_safe_file_dialog_options():
    options = QFileDialog.Options()
    if sys.platform.startswith("linux"):
        options |= QFileDialog.DontUseNativeDialog
        options |= QFileDialog.DontUseCustomDirectoryIcons
    return options


def get_runtime_base_dir() -> str:
    meipass_dir = getattr(sys, "_MEIPASS", "")
    if meipass_dir and os.path.isdir(meipass_dir):
        return meipass_dir
    return os.path.dirname(os.path.abspath(__file__))


def get_app_icon_path() -> str:
    base_dir = get_runtime_base_dir()
    icon_candidates = (
        "main_icon.ico",
        "favicon.png",
        "favicon-32.png",
        "favicon.ico",
        "favicon(1).ico",
        os.path.join("assets", "favicon.ico"),
    )
    for name in icon_candidates:
        candidate = os.path.join(base_dir, name)
        if os.path.exists(candidate):
            return candidate
    return ""


def ensure_linux_desktop_entry() -> None:
    if not sys.platform.startswith("linux"):
        return

    try:
        desktop_dir = os.path.join(os.path.expanduser("~"), ".local", "share", "applications")
        icon_dir = os.path.join(os.path.expanduser("~"), ".local", "share", "icons", "hicolor", "256x256", "apps")
        os.makedirs(desktop_dir, exist_ok=True)
        os.makedirs(icon_dir, exist_ok=True)

        source_icon = get_app_icon_path()
        target_icon = os.path.join(icon_dir, "astro-ai-plus.png")
        if source_icon:
            if source_icon.lower().endswith(".png"):
                shutil.copy2(source_icon, target_icon)
            else:
                converted = QImage(source_icon)
                if not converted.isNull():
                    converted.save(target_icon, "PNG")

        if getattr(sys, "frozen", False):
            exec_cmd = f'"{sys.executable}"'
            startup_wm_class = os.path.splitext(os.path.basename(sys.executable))[0]
        else:
            exec_cmd = f'python3 "{os.path.abspath(__file__)}"'
            startup_wm_class = "Astro Ai Plus"

        desktop_entry = "\n".join([
            "[Desktop Entry]",
            "Type=Application",
            "Version=1.0",
            "Name=Astro Ai Plus",
            f"Exec={exec_cmd}",
            f"Icon={target_icon}",
            "Terminal=false",
            "StartupNotify=true",
            f"StartupWMClass={startup_wm_class}",
            "Categories=Graphics;Science;",
            "",
        ])
        desktop_path = os.path.join(desktop_dir, "astro-ai-plus.desktop")
        with open(desktop_path, "w", encoding="utf-8") as f:
            f.write(desktop_entry)
    except Exception:
        pass


